import java.util.Scanner;

public class P1047D_Variant4 {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        long minDim = Math.min(rows, cols);
        long maxDim = Math.max(rows, cols);
        if (minDim == 1) {
            System.out.println((maxDim / 6) * 6 + 2 * Math.max(0, maxDim % 6 - 3));
        } else if (minDim == 2 && maxDim == 2) {
            System.out.println(0);
        } else if (minDim == 2 && maxDim == 3) {
            System.out.println(4);
        } else if (minDim == 3 && maxDim == 3) {
            System.out.println(8);
        } else if (minDim == 2 && maxDim == 7) {
            System.out.println(12);
        } else if (maxDim % 2 == 0) {
            System.out.println(minDim * maxDim);
        } else {
            System.out.println(minDim * maxDim - (minDim * maxDim) % 2);
        }
        scanner.close();
    }
}
</original_code>

